// Id PIF d'une espece nationale (null si l'espece n'est pas dans Infinite Fusion).
export function pifIdDepuisNational(idNat) {
  if (typeof idNat !== 'number') return null
  if (idNat >= 1 && idNat <= 251) return idNat
  return NATIONAL_VERS_PIF_EXTRA[idNat] || null
}

// Mapping inverse PIF -> national (construit une fois).
const PIF_VERS_NAT = (() => {
  const t = {}
  for (let i = 1; i <= 251; i++) t[i] = i
  for (const nat in NATIONAL_VERS_PIF_EXTRA) t[NATIONAL_VERS_PIF_EXTRA[nat]] = parseInt(nat)
  return t
})()
export function nationalDepuisPif(pif) { return PIF_VERS_NAT[pif] || null }

// Cache des listes decompressees (chaine -> Set) pour des lookups rapides.
const cacheListes = {}
function corpsDe(tetePif) {
  if (cacheListes[tetePif]) return cacheListes[tetePif]
  const brut = FUSIONS[tetePif]
  const s = brut ? new Set(brut.split(',').map(Number)) : new Set()
  cacheListes[tetePif] = s
  return s
}

// La fusion (tetePif, corpsPif) a-t-elle un sprite ? (sens ORIENTE)
export function spriteFusionExiste(tetePif, corpsPif) {
  return corpsDe(tetePif).has(corpsPif)
}

// Cherche une fusion entre deux especes NATIONALES (teste les 2 sens).
// Renvoie { tetePif, corpsPif } ou null.
export function trouverFusion(natA, natB) {
  const a = pifIdDepuisNational(natA)
  const b = pifIdDepuisNational(natB)
  if (!a || !b || a === b) return null
  if (spriteFusionExiste(a, b)) return { tetePif: a, corpsPif: b }
  if (spriteFusionExiste(b, a)) return { tetePif: b, corpsPif: a }
  return null
}

// Tous les partenaires (ids NATIONAUX) d'une espece nationale (les 2 sens confondus).
export function partenairesDe(natId) {
  const pif = pifIdDepuisNational(natId)
  if (!pif) return []
  const res = new Set()
  // pif comme tete
  for (const c of corpsDe(pif)) { const n = nationalDepuisPif(c); if (n) res.add(n) }
  // pif comme corps : parcourt les tetes
  for (const t in FUSIONS) { if (corpsDe(parseInt(t)).has(pif)) { const n = nationalDepuisPif(parseInt(t)); if (n) res.add(n) } }
  res.delete(natId)
  return [...res].sort((x, y) => x - y)
}

// Liste des especes nationales presentes dans le dex fusion (fusionnables).
export const ESPECES_FUSION = (() => {
  const res = []
  for (let i = 1; i <= 1025; i++) { if (pifIdDepuisNational(i)) res.push(i) }
  return res
})()